package com.universalplatform.finance;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.UUID;
@Entity @Table(name="payment")
class Payment { @Id UUID id; @Column(nullable=false) UUID tenantId; @Column(nullable=false) UUID invoiceId; @Column(nullable=false) UUID membershipId; @Column(nullable=false,precision=19,scale=2) BigDecimal amount; @Column(nullable=false,length=3) String currency; @Column(nullable=false,length=64) String provider; @Column(length=160) String providerReference; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) PaymentStatus status; String failureReason; Instant createdAt; Instant capturedAt; @Version long version;
 protected Payment(){} Payment(UUID id,UUID t,UUID i,UUID m,BigDecimal a,String c,String p,Instant at){this.id=id;tenantId=t;invoiceId=i;membershipId=m;amount=a;currency=c;provider=p;status=PaymentStatus.PENDING;createdAt=at;}
 UUID id(){return id;} UUID tenantId(){return tenantId;} UUID invoiceId(){return invoiceId;} UUID membershipId(){return membershipId;} BigDecimal amount(){return amount;} String currency(){return currency;} String provider(){return provider;} String providerReference(){return providerReference;} PaymentStatus status(){return status;} String failureReason(){return failureReason;} Instant createdAt(){return createdAt;} Instant capturedAt(){return capturedAt;} long version(){return version;}
 void authorize(String ref){status=PaymentStatus.AUTHORIZED;providerReference=ref;} void capture(Instant at){status=PaymentStatus.CAPTURED;capturedAt=at;} void fail(String r){status=PaymentStatus.FAILED;failureReason=r;} void refund(){if(status!=PaymentStatus.CAPTURED)throw new IllegalStateException("Only captured payments can be refunded");status=PaymentStatus.REFUNDED;}
}
